def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.25)
        return float(max(0.0, bid))

    total_players = 1 + len(alive)
    capacity = int(supply / WATER_REQ)
    scarcity = capacity < total_players

    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid') if prev else None
        if pbid is not None:
            prev_bids.append(float(pbid))
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            desperate_count += 1
        if opp.get('budget', 0) > 300 and pbid is not None and pbid >= 80:
            rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1
    if scarcity:
        urgency += 1
    if desperate_count >= max(1, len(alive) // 2):
        urgency += 1

    if urgency >= 5:
        base = max(DAILY_SALARY * 0.95, highest_prev + 4.0)
    elif urgency >= 3:
        base = max(DAILY_SALARY * 0.72, avg_prev + 2.5, highest_prev * 0.82)
    else:
        if scarcity:
            if highest_prev >= 100:
                base = DAILY_SALARY * 0.22
            elif highest_prev >= 80:
                base = DAILY_SALARY * 0.30
            else:
                base = max(DAILY_SALARY * 0.38, avg_prev * 0.72)
        else:
            base = max(DAILY_SALARY * 0.18, avg_prev * 0.45)

    if rich_aggressive >= 1 and urgency <= 2:
        base *= 0.85

    if day >= 8:
        if urgency >= 3:
            base = max(base, DAILY_SALARY * 0.85)
        else:
            base = max(base, DAILY_SALARY * 0.42)

    if budget < DAILY_SALARY * 1.2:
        if urgency >= 4:
            base = min(base, budget)
        else:
            base = min(base, budget * 0.55)
    elif budget < DAILY_SALARY * 2.5 and urgency <= 2:
        base = min(base, budget * 0.45)

    bid = min(budget, max(0.0, base))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    prev_bids = []
    for o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    # Baseline target bid: use yesterday's competitive level, but keep margin.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / max(1, len(prev_bids))
    else:
        highest_prev_bid = DAILY_SALARY * 0.55
        avg_prev_bid = DAILY_SALARY * 0.55

    # If any opponent shows high risk yesterday (low hp or many no-water days), slightly undercut.
    # If they were bidding high and survived, we need to match closer.
    risky_pressure = 0.0
    for o in alive_opps:
        if o.get('hp', 0) <= 2 or int(o.get('no_water_days', 0)) >= 2:
            risky_pressure += 1.0

    # Supply influences scarcity: higher supply reduces needed bid.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Convert to a competitive bid band.
    # When supply is low, bid closer to highest_prev_bid; when supply is high, bid closer to avg.
    scarcity_factor = 1.0 + (1.0 - supply_ratio) * 0.25

    target = avg_prev_bid * scarcity_factor

    # If highest_prev_bid is very high, align upward but not fully.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(target, highest_prev_bid * 0.92)
    else:
        target = max(target, highest_prev_bid * 0.75)

    # My urgency: if I'm low hp or have water shortage, increase bid.
    if hp <= 2.0 or no_water_days >= 1:
        target *= 1.15
    elif hp >= 7.0 and no_water_days == 0:
        target *= 0.9

    # If opponents are risky (likely to drop out), we can bid slightly less.
    if risky_pressure >= 1.0:
        target *= 0.97

    # Ensure within budget and sensible bounds.
    target = float(min(target, budget))

    # Hard cap to avoid overspending when budget is tight.
    # Keep enough budget for later days.
    if budget > 0:
        reserve = max(0.0, budget - DAILY_SALARY * 0.6)
        target = float(max(target, 0.0))
        # If reserve would leave too little, reduce bid.
        if target > budget - reserve:
            target = float(max(0.0, budget - reserve))

    # Minimum competitive bid: if we can afford it, bid at least a fraction of salary.
    min_bid = DAILY_SALARY * 0.35
    if budget >= min_bid:
        target = float(max(target, min_bid))

    # Final clamp.
    if target < 0.0:
        target = 0.0
    return float(target)
